const BRAND_COLORS: Record<string, string> = {
  aliyun: "#FF6A00",
  tencent: "#006EFF",
  "google-cloud": "#4285F4",
  aws: "#FF9900",
  azure: "#0089D6",
  cloudflare: "#F38020",
  digitalocean: "#0080FF",
}

interface ProviderIconProps {
  provider: string
  className?: string
  /** 是否使用品牌色（默认当前色） */
  colored?: boolean
}

/** 云厂商品牌图标：真实 logo，无网络依赖 */
export function ProviderIcon({ provider, className, colored = false }: ProviderIconProps) {
  const path = BRAND_PATHS[provider]
  const fill = colored ? BRAND_COLORS[provider] : "currentColor"
  if (!path) {
    return (
      <span className={cn("inline-flex items-center justify-center", className)}>
        <CloudGlyph />
      </span>
    )
  }
  return (
    <svg
      viewBox="0 0 24 24"
      role="img"
      aria-hidden="true"
      className={cn("size-4 shrink-0", className)}
      fill={fill}
    >
      <path d={path} />
    </svg>
  )
}

function CloudGlyph() {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className="size-4" aria-hidden="true">
      <path d="M6.5 20a4.5 4.5 0 0 1-.42-8.98 6 6 0 0 1 11.71-1.72A4.75 4.75 0 0 1 17.5 20h-11z" />
    </svg>
  )
}
